<template>
  <nut-notify></nut-notify>
  <nut-form>
    <nut-form-item label="申请校区">
      <view class="school-select" @click="toSelectSchool">
        <text :class="schoolName ? 'school-name' : 'school-placeholder'">
          {{ schoolName || '请选择申请校区' }}
        </text>
        <nut-icon name="right"></nut-icon>
      </view>
    </nut-form-item>

    <nut-form-item label="真实姓名">
      <nut-input v-model="form.realname" class="nut-input-text" placeholder="请输入姓名" type="text" />
    </nut-form-item>

    <nut-form-item label="性别">
      <nut-radio-group direction="horizontal" v-model="form.gender">
        <nut-radio label="1">男生</nut-radio>
        <nut-radio label="0">女生</nut-radio>
      </nut-radio-group>
    </nut-form-item>

    <nut-form-item label="学生证" label-position="top">
      <nut-uploader
        v-model:fileList="fileList"
        @success="uploadSuccess"
        @failure="uploadFailure"
        maximum="1"
        @file-item-click="imageClick"
        @oversize="oversize"
        :headers="headers"
        :data="uploaderData"
        :maximize="5242880"
        name="file"
        accept="image/*"
        :url="uploadUrl">
      </nut-uploader>
    </nut-form-item>
  </nut-form>

  <view class="submit-bar">
    <nut-button :loading="btnLoading" @click="submit" block type="info">
      提交审核
    </nut-button>
  </view>
</template>

<script setup>
</script>

<script>
import { runnerSubmit } from "@/request/apis/runner.js";
import { upload_url } from "@/request/request.js";
import { useNotify } from "nutui-uniapp/composables";

export default {
  setup() {
    const notify = useNotify();
    const showSuccess = (message) => { notify.success(message); };
    const showDanger = (message) => { notify.danger(message); };
    const showWarning = (message) => { notify.warning(message); };
    return { showSuccess, showDanger, showWarning };
  },
  data() {
    return {
      fileList: [],
      school: {},
      schoolName: "",
      back: false,
      uploadUrl: upload_url,
      form: {
        schoolId: "",
        schoolName: "",
        cityCode: "",
        cityName: "",
        realname: "",
        gender: "1",
        studentCardUrl: ""
      },
      headers: {
        Authorization: "Bearer " + uni.getStorageSync("token")
      },
      uploaderData: {
        type: 5,
        name: ""
      },
      btnLoading: false
    };
  },
  onLoad() {
    this.initData();
  },
  onShow() {
    this.initData();
  },
  methods: {
    submit() {
      if (!this.form.schoolId) {
        this.showWarning("请先选择申请校区");
        return;
      }
      if (!this.form.realname || !this.form.realname.trim()) {
        this.showWarning("请填写真实姓名");
        return;
      }
      if (!this.form.studentCardUrl) {
        this.showWarning("请先上传学生证");
        return;
      }

      this.btnLoading = true;
      runnerSubmit(this.form).then(() => {
        this.showSuccess("提交成功");
        setTimeout(() => {
          uni.navigateBack();
        }, 1000);
      }).catch(err => {
        this.showDanger(this.getErrorMessage(err, "提交失败"));
      }).finally(() => {
        this.btnLoading = false;
      });
    },
    initData() {
      const storeSchool = this.$store.state.currSchool;
      const storageSchool = uni.getStorageSync("currentSchool");
      const school = storeSchool && storeSchool.id ? storeSchool : storageSchool;

      if (school && school.id) {
        this.school = school;
        this.schoolName = school.name;
        this.form.schoolId = school.id;
        this.form.schoolName = school.name;
        const city = uni.getStorageSync("currentCity") || {};
        this.form.cityCode = city.cityCode || city.adcode || "";
        this.form.cityName = city.cityName || city.name || "";
      }
    },
    toSelectSchool() {
      uni.navigateTo({
        url: "/pages/API/school/select/select?back=1"
      });
    },
    imageClick(file) {
      const fileItem = file.fileItem || file;
      const url = fileItem.url || this.form.studentCardUrl;
      if (!url) {
        return;
      }
      uni.previewImage({
        current: 0,
        urls: [url]
      });
    },
    oversize() {
      uni.showToast({
        title: "文件大小超出5MB",
        icon: "none"
      });
    },
    uploadSuccess(e) {
      try {
        const response = this.parseUploadResponse(e);
        if (response.code !== 200 || !response.data || !response.data.url) {
          this.showDanger(response.msg || "上传失败");
          return;
        }
        this.form.studentCardUrl = response.data.url;
        this.showSuccess("学生证上传成功");
      } catch (err) {
        this.showDanger("上传结果解析失败");
      }
    },
    uploadFailure(e) {
      console.log(e);
      this.showDanger("学生证上传失败");
    },
    parseUploadResponse(e) {
      let raw = e && e.data ? e.data : e;
      if (raw && raw.code === undefined && raw.data) {
        raw = raw.data;
      }
      if (typeof raw === "string") {
        raw = JSON.parse(raw);
      }
      return raw || {};
    },
    getErrorMessage(err, fallback) {
      if (typeof err === "string") {
        return err;
      }
      if (err && err.msg) {
        return err.msg;
      }
      return fallback;
    }
  }
};
</script>

<style>
.submit-bar {
  position: fixed;
  bottom: 6%;
  width: 90%;
  margin-left: 5%;
}

.school-select {
  width: 100%;
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.school-name {
  color: #333;
  font-size: 14px;
}

.school-placeholder {
  color: #999;
  font-size: 14px;
}

.custom-content {
  padding: 10px 10px 160px;
}

.nut-cell-group__wrap {
  padding: 0 10px !important;
}

.nut-uploader__upload {
  width: 100% !important;
  height: 160px !important;
}

.nut-uploader__preview-img {
  width: 100% !important;
  height: 160px !important;
}
</style>
